(missing)))\n201\t\n202\t    # 4. Priority inheritance — enablers of P0 work must be P0\n203\t    for k in sorted(epics):\n204\t        if is_branch[k] or is_docs[k]:\n205\t            continue\n206\t        if prio.get(k) != \"P0\":\n207\t            continue\n208\t        # every main-plan, non-docs epic in k's closure enables P0 work\n209\t        cl = dependency_closure(k, deps)\n210\t        for t in sorted(cl):\n211\t            if is_branch[t] or is_docs[t]:\n212\t                continue\n213\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n214\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n215\t                             \"but is %s — raise it to P0 or restructure\"\n216\t                             % (t, prio.get(t), k, prio.get(t)))\n217\t\n218\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n219\t    #    pairs carry no dependencies edge in either direction (direct edges\n220\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n221\t    #    them; dependencies naming epics with no file cannot be judged).\n222\t    for k in sorted(epics):\n223\t        if kind(k) == \"docs-authoring\":\n224\t            continue\n225\t        for t in deps[k]:\n226\t            if t not in epics:\n227\t                continue\n228\t            pair = frozenset((kind(t), kind(k)))\n229\t            rule = PARALLEL_PAIRS.get(pair)\n230\t            if rule:\n231\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n232\t                             \"parallel; remove the dependencies edge and \"\n233\t                             \"express any coupling as an AC gate on the \"\n234\t                             \"dependent epic\"\n235\t                             % (rule, t, kind(t), k, kind(k)))\n236\t\n237\t    # 6. Shared-surface enforcement deliverable — a general Implementation\n238\t    #    epic whose title names an enforcement tool AND shares its component\n239\t    #    with another non-docs Implementation epic is a work-type extraction:\n240\t    #    the enforcement work must be divided per surface into the consuming\n241\t    #    epics, not carved into a standalone work-type epic. Exempt when the\n242\t    #    enforcement tool is the component's only implementation work.\n243\t    impl_keys = sorted(k for k in epics\n244\t                       if is_impl[k] and not is_branch[k] and not is_docs[k])\n245\t    for k in impl_keys:\n246\t        if itype[k] is not None:  # routed labels are never the extraction\n247\t            continue\n248\t        if not ENFORCEMENT_TITLE_RE.search(titles[k]):\n249\t            continue\n250\t        siblings = [j for j in impl_keys\n251\t                    if j != k and comps[j] and comps[j] == comps[k]]\n252\t        if not siblings:\n253\t            continue\n254\t        probs.append(\"%s: standalone enforcement deliverable — an enforcement \"\n255\t                     \"tool ('%s') shared with other implementation work in \"\n256\t                     \"the same component must be divided per surface into \"\n257\t                     \"each consuming epic's Scope and Acceptance Criteria, \"\n258\t                     \"not extracted into a work-type epic; FIX: fold the \"\n259\t                     \"enforcement work back into every epic whose surface it \"\n260\t                     \"covers (as scope + a verification AC), delete this \"\n261\t                     \"epic, and update the summary's Epic List, DAG diagram \"\n262\t                     \"and traceability matrix\"\n263\t                     % (k + \".md\", titles[k]))\n264\t    return probs\n265\t\n266\t\n267\t# ─── self-check ───────────────────────────────────────────────────────────────\n268\t\n269\tdef _self_check():\n270\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n271\t    import shutil\n272\t    import tempfile\n273\t\n274\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n275\t    try:\n276\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n277\t        os.makedirs(art)\n278\t        comp = os.path.join(tmp, \"components.txt\")\n279\t        with open(comp, \"w\") as f:\n280\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n281\t\n282\t        def write(name, fm, body):\n283\t            with open(os.path.join(art, name), \"w\") as f:\n284\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n285\t\n286\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n287\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n288\t        write(\"RHAISTRAT-9001-E001.md\",\n289\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n290\t              \"dependencies: []\\n\", good_body)\n291\t        write(\"RHAISTRAT-9001-E002.md\",\n292\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n293\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n294\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003]\\n\",\n295\t              good_body)\n296\t        # a konflux-onboarding epic parallel to the general epic (no edge\n297\t        # either way) is the Rule 10-compliant shape — must not be flagged\n298\t        write(\"RHAISTRAT-9001-E003.md\",\n299\t              \"component: Dashboard\\ntype: Implementation\\n\"\n300\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n301\t              \"dependencies: []\\n\", good_body)\n302\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n303\t                     comp) == [], \"good fixture must pass cleanly\"\n304\t\n305\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge,\n306\t        # Rule 10 konflux-onboarding -> general edge\n307\t        write(\"RHAISTRAT-9002-E001.md\",\n308\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n309\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n310\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n311\t              \"## HLR Traceability\\nh\\n\")\n312\t        write(\"RHAISTRAT-9002-E002.md\",\n313\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n314\t              \"dependencies: []\\n\", good_body)\n315\t        write(\"RHAISTRAT-9002-E003.md\",\n316\t              \"component: Dashboard\\ntype: Implementation\\n\"\n317\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n318\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n319\t        # E004 is a main-plan Implementation the docs epic never depends on\n320\t        write(\"RHAISTRAT-9002-E004.md\",\n321\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n322\t              \"dependencies: [RHAISTRAT-9002-E005]\\n\", good_body)\n323\t        write(\"RHAISTRAT-9002-E005.md\",\n324\t              \"component: Dashboard\\ntype: Implementation\\n\"\n325\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n326\t              \"dependencies: []\\n\", good_body)\n327\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n328\t        joined = \"\\n\".join(probs)\n329\t        assert \"missing 'Scope'\" in joined, probs\n330\t        assert \"Model Serving Stack\" in joined, probs\n331\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n332\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n333\t        r10 = [p for p in probs if p.startswith(\"Rule 10:\")]\n334\t        assert len(r10) == 1 and \"E005\" in r10[0] and \"E004\" in r10[0], probs\n335\t\n336\t        # check 6 — work-type extraction of a shared-surface enforcement\n337\t        # deliverable: bad shape (standalone lint-rule epic sharing the\n338\t        # component with two other general Implementation epics) vs. the two\n339\t        # exempt shapes (enforcement tool as the component's only\n340\t        # implementation work; per-surface division — no standalone epic).\n341\t        write(\"RHAISTRAT-9003-E001.md\",\n342\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n343\t              \"title: Convert manager binary log calls\\n\"\n344\t              \"dependencies: []\\n\", good_body)\n345\t        write(\"RHAISTRAT-9003-E002.md\",\n346\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n347\t              \"title: Convert cloudmanager binary log calls\\n\"\n348\t              \"dependencies: []\\n\", good_body)\n349\t        write(\"RHAISTRAT-9003-E003.md\",\n350\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n351\t              \"title: CI lint rule enforcing structured log fields\\n\"\n352\t              \"dependencies: []\\n\", good_body)\n353\t        probs3 = check(\"RHAISTRAT-9003\", os.path.join(tmp, \"artifacts\"), comp)\n354\t        c6 = [p for p in probs3 if \"standalone enforcement deliverable\" in p]\n355\t        assert len(c6) == 1 and \"RHAISTRAT-9003-E003.md\" in c6[0], probs3\n356\t        # exemption: enforcement tool is the component's only implementation\n357\t        # work — the deliverable itself, not an extraction\n358\t        write(\"RHAISTRAT-9004-E001.md\",\n359\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n360\t              \"priority: P0\\ntitle: Repo-wide lint rule for API docs\\n\"\n361\t              \"dependencies: []\\n\", good_body)\n362\t        assert check(\"RHAISTRAT-9004\", os.path.join(tmp, \"artifacts\"),\n363\t                     comp) == [], \"lone enforcement epic must pass cleanly\"\n364\t        print(\"self-check OK: 6 checks fire on bad fixture, clean on good\")\n365\t        return 0\n366\t    finally:\n367\t        shutil.rmtree(tmp, ignore_errors=True)\n368\t\n369\t\n370\tdef main(argv=None):\n371\t    ap = argparse.ArgumentParser(description=__doc__)\n372\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n373\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n374\t    ap.add_argument(\"--components\",\n375\t                    default=\".context/rhai-components.txt\")\n376\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n377\t    args = ap.parse_args(argv)\n378\t\n379\t    if args.self_check:\n380\t        return _self_check()\n381\t    if not args.strat_id:\n382\t        ap.error(\"strat_id is required (unless --self-check)\")\n383\t\n384\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n385\t    if probs:\n386\t        for p in probs:\n387\t            print(\"VIOLATION: %s\" % p)\n388\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n389\t              \"complete\" % len(probs))\n390\t        return 1\n391\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n392\t    return 0\n393\t\n394\t\n395\tif __name__ == \"__main__\":\n396\t    sys.exit(main())\n397\t"}]},"parent_tool_use_id":"chatcmpl-tool-a580b57804d2fe22","agent_id":"af8a167483ade832b","session_id":"24eb6c29-6a9a-48c1-874c-32ca163b119c","uuid":"e1ffbdd6-850a-46dc-b71e-6927a318abbf","timestamp":"2026-10-26T19:38:06.744Z","tool_result_meta":[{"id":"chatcmpl-tool-aac5311e71f6a42b","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"claude","task_description":"Decompose RHAISTRAT-8010"}
